package main

import (
	"fmt"
	"strconv"
)

func main() {
	// init statement: parse, then test, with err scoped to the if/else only
	if n, err := strconv.Atoi("42"); err != nil {
		fmt.Println("parse failed:", err)
	} else {
		fmt.Println("parsed:", n*2) // n and err are visible in this else too
	}
	// err is NOT visible here — it was scoped to the if statement

	prices := map[string]int{"pen": 3, "book": 12}
	// comma-ok with init: v and ok live only inside the if/else
	if v, ok := prices["book"]; ok {
		fmt.Println("book costs", v)
	} else {
		fmt.Println("book not found")
	}

	// if / else-if ladder (no parentheses, braces mandatory)
	score := 84
	if score >= 90 {
		fmt.Println("grade A")
	} else if score >= 80 {
		fmt.Println("grade B")
	} else {
		fmt.Println("grade C or below")
	}
}

package main

import "fmt"

func main() {
	// 1) Classic three-clause counted loop
	sum := 0
	for i := 1; i <= 5; i++ {
		sum += i
	}
	fmt.Println("sum 1..5 =", sum)

	// 2) Condition-only loop — Go's "while"
	n := 8
	steps := 0
	for n > 1 {
		n /= 2
		steps++
	}
	fmt.Println("halvings:", steps)

	// 3) Infinite loop with an explicit exit (break)
	count := 0
	for {
		if count == 3 {
			break
		}
		count++
	}
	fmt.Println("count reached", count)

	// 4) for range over a slice; v is a COPY of each element
	nums := []int{10, 20, 30}
	for i, v := range nums {
		if v == 20 {
			continue // skip the rest of this iteration
		}
		fmt.Printf("index %d value %d\n", i, v)
	}

	// Labeled break to escape nested loops at once
outer:
	for r := 0; r < 3; r++ {
		for c := 0; c < 3; c++ {
			if r+c == 3 {
				fmt.Printf("stopping at r=%d c=%d\n", r, c)
				break outer
			}
		}
	}
}

package main

import "fmt"

func describeDay(day string) string {
	// Expression switch with multi-value cases; cases auto-break (no fall-through)
	switch day {
	case "Sat", "Sun":
		return "weekend"
	case "Fri":
		return "almost weekend"
	default:
		return "weekday"
	}
}

func classify(score int) string {
	// Expression-less switch: each case is a boolean — an if/else-if ladder
	switch {
	case score >= 90:
		return "A"
	case score >= 80:
		return "B"
	default:
		return "C"
	}
}

func rank(n int) {
	// Explicit fallthrough: control enters the NEXT case unconditionally
	switch {
	case n >= 2:
		fmt.Print("silver ")
		fallthrough
	case n >= 1:
		fmt.Print("bronze ")
	default:
		fmt.Print("none")
	}
	fmt.Println()
}

func kindOf(i interface{}) string {
	// Type switch: branch on the dynamic type; v has the concrete type per case
	switch v := i.(type) {
	case int:
		return fmt.Sprintf("int doubled = %d", v*2)
	case string:
		return fmt.Sprintf("string of len %d", len(v))
	case bool:
		return fmt.Sprintf("bool = %t", v)
	default:
		return fmt.Sprintf("unknown type %T", v)
	}
}

func main() {
	fmt.Println(describeDay("Sat"))
	fmt.Println(classify(84))
	rank(2)
	fmt.Println(kindOf(21))
	fmt.Println(kindOf("hi"))
	fmt.Println(kindOf(3.14))
}
